//! Shapes of the bundled tables generated by `build.rs` (see its module doc for
//! the application union). FIXT keeps independent source-local tables.

use std::borrow::Cow;

use super::model::Datatype;
use super::schema::{member, row, span, ComponentRow, Member, Schema, ScopeSpan, NONE};

/// Bit `i` = the application whose `StaticDict::mask_bit()` is `Some(i)` (the
/// ordinal `build.rs` assigns, in `BUNDLED_VERSIONS` order).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct VersionMask(pub u16);

impl VersionMask {
    /// How many bundled versions a mask can address; `build.rs` asserts against it.
    pub const BITS: usize = 16;

    /// The only place that interprets the mask; `mask_bit` values are ordinals.
    pub const fn contains(self, ordinal: u8) -> bool {
        self.0 & (1 << ordinal) != 0
    }
}

/// One tag across application releases. Base values are the newest source's;
/// an override row records what the versions in its mask see instead.
#[derive(Debug)]
pub struct TagRecord {
    pub tag: u32,
    pub name: &'static str,
    pub datatype: &'static str,
    pub datatype_class: Datatype,
    pub description: &'static str,
    /// Recorded FIX release for this field's introduction; empty when undated.
    pub added: &'static str,
    /// FIX release that deprecated this field; empty when unrecorded.
    pub deprecated: &'static str,
    /// The extension pack recorded against `added`, or 0 when none is. No
    /// override bucket: every version is enriched from one metadata file, so
    /// this cannot differ between them, and `build.rs` asserts it.
    pub added_ep: u16,
    pub presence: VersionMask,
    /// The versions whose value list is open (`allowOtherValues`).
    pub allows_other_values: VersionMask,
    pub overrides: &'static [FieldOverride],
    /// Sorted by `value`; each carries its own presence mask.
    pub enums: &'static [EnumRecord],
}

/// Version-specific field attributes; `None` inherits the base `TagRecord` value.
#[derive(Debug)]
pub struct FieldOverride {
    pub versions: VersionMask,
    pub name: Option<&'static str>,
    pub datatype: Option<&'static str>,
    pub datatype_class: Option<Datatype>,
    pub description: Option<&'static str>,
    /// Override for the FIX release that introduced this field.
    pub added: Option<&'static str>,
    /// Override for the FIX release that deprecated this field.
    pub deprecated: Option<&'static str>,
}

/// One field's enum value across application releases, with version-specific overrides.
#[derive(Debug)]
pub struct EnumRecord {
    pub value: &'static str,
    pub name: &'static str,
    pub description: &'static str,
    /// Recorded FIX release for this enum value's introduction; empty when undated.
    pub added: &'static str,
    /// Extension pack that introduced this enum value; 0 when unrecorded.
    pub added_ep: u16,
    pub presence: VersionMask,
    pub overrides: &'static [EnumOverride],
}

/// Version-specific enum attributes; `None` inherits the base `EnumRecord` value.
#[derive(Debug)]
pub struct EnumOverride {
    pub versions: VersionMask,
    pub name: Option<&'static str>,
    pub description: Option<&'static str>,
    /// Override for the FIX release that introduced this enum value.
    pub added: Option<&'static str>,
}

#[derive(Debug)]
pub struct StaticGroup {
    pub name: &'static str,
    pub count_tag: u32,
    pub delimiter_tag: u32,
}

#[derive(Debug)]
pub struct StaticMessage {
    pub msg_type: &'static str,
    pub name: &'static str,
    pub category: &'static str,
    pub description: &'static str,
}

/// Application history and standalone source storage have separate indices.
#[derive(Debug)]
pub enum StaticFields {
    /// `mask_bit` selects this source's application history in the merged `TAGS` table.
    Application { mask_bit: u8 },
    /// Field indices address this source-local table without version masks.
    Standalone(&'static [StandaloneField]),
}

/// Field metadata in a bundled source that has no application-history mask.
#[derive(Debug)]
pub struct StandaloneField {
    pub tag: u32,
    pub name: &'static str,
    pub datatype: &'static str,
    pub datatype_class: Datatype,
    pub description: &'static str,
    /// Recorded FIX release for this field's introduction; empty when undated.
    pub added: &'static str,
    /// FIX release that deprecated this field; empty when unrecorded.
    pub deprecated: &'static str,
    /// Extension pack that introduced this field; 0 when unrecorded.
    pub added_ep: u16,
    /// True when the field accepts values that `enums` does not list. The XML
    /// attribute is `allowOtherValues`.
    pub allows_other_values: bool,
    /// Sorted by wire value for enum lookup.
    pub enums: &'static [StandaloneEnum],
}

/// Enum metadata for one field in a standalone bundled source.
#[derive(Debug)]
pub struct StandaloneEnum {
    pub value: &'static str,
    pub name: &'static str,
    pub description: &'static str,
    /// Recorded FIX release for this enum value's introduction; empty when undated.
    pub added: &'static str,
    /// Extension pack that introduced this enum value; 0 when unrecorded.
    pub added_ep: u16,
}

/// One bundled dictionary source with its field storage and schema tables.
#[derive(Debug)]
pub struct StaticDict {
    pub version: &'static str,
    pub fields: StaticFields,
    pub schema: Schema<'static>,
    pub groups: &'static [StaticGroup],
    pub messages: &'static [StaticMessage],
}

impl StaticDict {
    pub fn mask_bit(&self) -> Option<u8> {
        match self.fields {
            StaticFields::Application { mask_bit } => Some(mask_bit),
            StaticFields::Standalone(_) => None,
        }
    }
}

/// A tag FIX Latest defines and no bundled dictionary does. `LATEST_TAGS` is
/// sorted by tag.
#[derive(Debug)]
pub struct LatestTag {
    pub tag: u32,
    pub name: &'static str,
    /// Field introduction release index in `LATEST_VERSIONS`; avoids a string relocation.
    pub added: u8,
    /// Extension pack that introduced this field; 0 when unrecorded.
    pub added_ep: u16,
}

impl TagRecord {
    pub fn override_for(&self, bit: u8) -> Option<&'static FieldOverride> {
        self.overrides.iter().find(|o| o.versions.contains(bit))
    }
}

impl EnumRecord {
    pub fn override_for(&self, bit: u8) -> Option<&'static EnumOverride> {
        self.overrides.iter().find(|o| o.versions.contains(bit))
    }
}

include!(concat!(env!("OUT_DIR"), "/dicts.rs"));
